function validate([num]) {
  if (num.length < 1 || num.length > 50) return 'num needs 1 to 50 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may only contain digits.';
  if (num.length > 1 && num[0] === '0') return 'num cannot have a leading zero.';
  return null;
}

