function isStrobogrammatic(num) {
  const rotated = new Map([['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']]);
  let left = 0;
  let right = num.length - 1;

  while (left <= right) {
    if (rotated.get(num[left]) !== num[right]) {
      return false;
    }
    left++;
    right--;
  }
  return true;
}

