function isStrobogrammatic(num) {
  // Rotate the whole string: reverse the order, then turn each digit upside down.
  let turned = '';
  for (let i = num.length - 1; i >= 0; i--) {
    const d = num[i];
    if (d === '0' || d === '1' || d === '8') turned += d;
    else if (d === '6') turned += '9';
    else if (d === '9') turned += '6';
    else return false;
  }
  return turned === num;
}

